#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_LANDMZ FW_1TO1_NAT FW_PORTFORWARDING FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_vendor_vpn && fail 'an IP group named fws_vendor_vpn exists; nothing was written'
named FW_GROUP_IP fws_scada && fail 'an IP group named fws_scada exists; nothing was written'
named FW_GROUP_IP fws_plc_cell1 && fail 'an IP group named fws_plc_cell1 exists; nothing was written'
named FW_GROUP_PORT fws_tcp-web && fail 'a port group named fws_tcp-web exists; nothing was written'
named FW_GROUP_PORT fws_tcp-s7_iso && fail 'a port group named fws_tcp-s7_iso exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_vendor_vpn --set .COMMENT 'FWShift: vendor_vpn'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.64/27
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_scada --set .COMMENT 'FWShift: scada'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/28
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP historian.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_plc_cell1 --set .COMMENT 'FWShift: plc_cell1'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.20-192.168.10.29
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.40
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-web --set .COMMENT 'FWShift: tcp-web'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-s7_iso --set .COMMENT 'FWShift: tcp-s7_iso'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 102
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 20000-20010
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 502 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'incoming-1: Modbus/TCP from "SCADA" to the PLCs'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_scada
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_plc_cell1
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO icmp --set .FROM_IP 198.51.100.0/24 --set .FROM_PORT any --set .IN_IP 192.168.10.0/24 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'incoming-2: ping from the control centre'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 192.168.10.0/24 --set .IN_PORT 0 --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'incoming-3: no web from outside'
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_tcp-web
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 161 --set .TARGET_REF REJECT --set .LOG no --set .COMMENT 'incoming-4: SNMP refused'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 192.168.10.0/24 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'incoming-6.vendor-1: S7 for the vendor'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_vendor_vpn
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_tcp-s7_iso
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'incoming-6.vendor-2: nothing else from the vendor'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_vendor_vpn
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO gre --set .FROM_IP 198.51.100.7 --set .FROM_PORT any --set .IN_IP 192.168.10.5 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'incoming-7: GRE of a legacy tunnel; the port is ignored'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 198.51.100.0/24 --set .FROM_PORT 1024:65535 --set .IN_IP 192.168.10.50 --set .IN_PORT 8000:8080 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'incoming-8: HMI web, published by 1:1 NAT (the rule names the real address)'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'outgoing-1: the PLCs do not talk out'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_plc_cell1
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 192.168.10.1 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'outgoing-2: DNS'
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'outgoing-3: web out'
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_tcp-web
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.20.0/24 --set .FROM_PORT any --set .IN_IP 192.168.10.0/24 --set .IN_PORT 102 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'outgoing-4: engineering VLAN 20 to the S7 PLCs'
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 172.16.30.10 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'wan-dmz-1: the DMZ web server'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_tcp-web
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO tcp --set .FROM_IP 172.16.30.10 --set .FROM_PORT any --set .IN_IP 192.168.10.60 --set .IN_PORT 1433 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'dmz-lan-1: web server to the historian database'
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'lan-dmz-1: LAN to DMZ: everything (the factory rule)'
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 192.168.10.48 --set .REMOTE_NET 203.0.113.8 --set .MASK 29 --set .ENABLE_ARP yes --set .COMMENT '1to1-1: HMI subnet published'
N=$((N+1))

# FW_PORTFORWARDING
N=$(rows FW_PORTFORWARDING)
gc --silent --goto FW_PORTFORWARDING --add-row --set .PROTO tcp --set .SRC_IP 0.0.0.0/0 --set .SRC_PORT any --set .IN_IP %extern --set .IN_PORT 8443 --set .OUT_IP 192.168.10.30 --set .OUT_PORT 443 --set .LOG yes --set .COMMENT 'portforward-1: remote HMI'
N=$((N+1))
gc --silent --goto FW_PORTFORWARDING --add-row --set .PROTO udp --set .SRC_IP 0.0.0.0/32 --set .SRC_PORT any --set .IN_IP 203.0.113.3 --set .IN_PORT 47808 --set .OUT_IP 172.16.30.20 --set .OUT_PORT 47808 --set .LOG no --set .COMMENT 'portforward-2: BACnet gateway in the DMZ'
gc --silent --set-refname "FW_PORTFORWARDING.$N.SRC_IP" fws_vendor_vpn
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --silent --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 192.168.10.0/24 --set .COMMENT 'masquerade-1: LAN out to the WAN'
N=$((N+1))
gc --goto FW_NAT --add-row --set .EXT_IF int --set .IN_IP 172.16.30.0/24 --set .COMMENT 'masquerade-2: DMZ hosts reach the LAN as the mGuard'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
